import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.CHjbm2Wd.js";const u=JSON.parse('{"title":"Resources","description":"A curated, opinionated list of the documents, tools, books, and datasets worth your time — and what each one is actually for.","frontmatter":{"title":"Resources","description":"A curated, opinionated list of the documents, tools, books, and datasets worth your time — and what each one is actually for."},"headers":[],"relativePath":"reference/resources.md","filePath":"reference/resources.md","lastUpdated":1792993690000}'),n={name:"reference/resources.md"};function s(d,t,i,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h1><p>Most reading lists are too long to use. This one is filtered for a specific goal: becoming employable on a lunar lander GNC or flight-software team. Each entry says <strong>what it is for</strong> and <strong>when to use it</strong>. Links change; search the title if a URL rots.</p><div class="tip custom-block"><p class="custom-block-title">How to use this page</p><p>Do not read the list top to bottom. Pick the section that matches your current week, choose <strong>one</strong> primary source, and use the rest as reference. A book you work through beats five books you bookmark.</p></div><h2 id="the-documents-that-define-the-job" tabindex="-1">The documents that define the job <a class="header-anchor" href="#the-documents-that-define-the-job" aria-label="Permalink to &quot;The documents that define the job&quot;">​</a></h2><p>These are the sources a real program will point you to. Read them early enough to learn the vocabulary, not so early that they replace the concepts.</p><table tabindex="0"><thead><tr><th>Document</th><th>Use it for</th><th>Access</th></tr></thead><tbody><tr><td><a href="https://nodis3.gsfc.nasa.gov/displayDir.cfm?t=NPR&amp;c=7150&amp;s=2" target="_blank" rel="noreferrer">NPR 7150.2 — NASA Software Engineering Requirements</a></td><td>Software classes, lifecycle evidence, assurance requirements</td><td>Free</td></tr><tr><td><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA Software Engineering Handbook (SWEHB)</a></td><td>Practical guidance for each NPR requirement</td><td>Free</td></tr><tr><td><a href="https://www.nasa.gov/connect/ebooks/nasa-systems-engineering-handbook/" target="_blank" rel="noreferrer">NASA Systems Engineering Handbook</a></td><td>Requirements, interfaces, verification, risk</td><td>Free PDF</td></tr><tr><td><a href="https://standards.nasa.gov/" target="_blank" rel="noreferrer">NASA-STD-8739.8 — Software Assurance</a></td><td>Assurance tasks and independence</td><td>Free</td></tr><tr><td><a href="https://public.ccsds.org/Pubs/133x0b2.pdf" target="_blank" rel="noreferrer">CCSDS Space Packet Protocol (133.0-B)</a></td><td>APID, sequence, packet structure</td><td>Free</td></tr><tr><td><a href="https://public.ccsds.org/Pubs/132x0b3.pdf" target="_blank" rel="noreferrer">CCSDS Telemetry Transfer Frame (132.0-B)</a></td><td>Frames, virtual channels, Reed–Solomon</td><td>Free</td></tr><tr><td><a href="https://public.ccsds.org/Pubs/232x0b4.pdf" target="_blank" rel="noreferrer">CCSDS COP-1 (232.0-B)</a></td><td>Reliable command transfer</td><td>Free</td></tr><tr><td><a href="https://ecss.nl/" target="_blank" rel="noreferrer">SpaceWire Standard (ECSS-E-ST-50-12C)</a></td><td>Link layer, packets, routing</td><td>Free</td></tr><tr><td><a href="https://github.com/nasa/cFS" target="_blank" rel="noreferrer">NASA cFS documentation</a></td><td>Application model, services, build</td><td>Free</td></tr></tbody></table><p><strong>How to read NPR 7150.2 without drowning:</strong> start with the software class definitions and the lifecycle table. Then pick one requirement that applies to your capstone (for example, unit test coverage or requirements traceability) and build the evidence. A crosswalk of ten requirements you actually satisfied is more credible than a claim of full compliance.</p><h2 id="flight-software-and-real-time-systems" tabindex="-1">Flight software and real-time systems <a class="header-anchor" href="#flight-software-and-real-time-systems" aria-label="Permalink to &quot;Flight software and real-time systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://github.com/nasa/cFS" target="_blank" rel="noreferrer">NASA cFS</a></td><td>The reference architecture. Build one app, send one command, downlink one telemetry point.</td></tr><tr><td><a href="https://github.com/nasa/cFS/blob/main/doc/cFS_Training_Slides.pdf" target="_blank" rel="noreferrer">cFS Training</a></td><td>A guided tour of the framework.</td></tr><tr><td><a href="https://github.com/nasa/cFE" target="_blank" rel="noreferrer">cFE</a> and <a href="https://github.com/nasa/cFS_Apps" target="_blank" rel="noreferrer">cFS Apps</a></td><td>Services and example applications.</td></tr><tr><td><a href="https://github.com/nasa/HS" target="_blank" rel="noreferrer">NASA HS (Health &amp; Safety)</a></td><td>Watchdog, CPU monitoring, and recovery patterns.</td></tr><tr><td><a href="https://github.com/nasa/sch" target="_blank" rel="noreferrer">NASA Sch (Scheduler)</a></td><td>Rate-group scheduling in practice.</td></tr><tr><td><a href="https://www.freertos.org/" target="_blank" rel="noreferrer">FreeRTOS</a></td><td>Tasks, queues, semaphores, priority inversion. The cheapest way to learn an RTOS.</td></tr><tr><td><a href="https://www.rtems.org/" target="_blank" rel="noreferrer">RTEMS</a></td><td>Open-source RTOS used in space; POSIX-like and certifiable.</td></tr><tr><td><a href="https://www.windriver.com/products/vxworks" target="_blank" rel="noreferrer">VxWorks</a></td><td>Widely used in flight; documentation is public, the product is not.</td></tr><tr><td><a href="https://barrgroup.com/embedded-systems/books/embedded-c-coding-standard" target="_blank" rel="noreferrer">Barr Group, <em>Embedded C Coding Standard</em></a></td><td>The rules that prevent whole classes of embedded bugs.</td></tr><tr><td><a href="https://www.misra.org.uk/" target="_blank" rel="noreferrer">MISRA C</a></td><td>The automotive/industrial safety subset; useful discipline even if your program does not require it.</td></tr><tr><td><a href="https://en.wikipedia.org/wiki/The_Power_of_Ten_(coding_standards)" target="_blank" rel="noreferrer">JPL Power of Ten</a></td><td>Ten rules for safety-critical code. Short, blunt, worth memorizing.</td></tr></tbody></table><p><strong>Build order:</strong> cFS app → FreeRTOS task/queue exercise → timing measurement → fault injection. Reading about schedulers without measuring jitter teaches you the vocabulary but not the behavior.</p><h2 id="gnc-dynamics-and-control" tabindex="-1">GNC, dynamics, and control <a class="header-anchor" href="#gnc-dynamics-and-control" aria-label="Permalink to &quot;GNC, dynamics, and control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://www.springer.com/gp/book/9781881883142" target="_blank" rel="noreferrer">Vallado, <em>Fundamentals of Astrodynamics and Applications</em></a></td><td>The standard orbital mechanics reference. Buy or borrow; you will use it for years.</td></tr><tr><td><a href="https://arc.aiaa.org/doi/book/10.2514/4.105210" target="_blank" rel="noreferrer">Schaub &amp; Junkins, <em>Analytical Mechanics of Space Systems</em></a></td><td>Rigid-body dynamics, attitude control, and spacecraft mechanics.</td></tr><tr><td><a href="https://arc.aiaa.org/doi/book/10.2514/4.862106" target="_blank" rel="noreferrer">Wie, <em>Space Vehicle Dynamics and Control</em></a></td><td>A control-first treatment; good for quaternions and Lyapunov methods.</td></tr><tr><td><a href="https://www.sciencedirect.com/book/9780124807016/stochastic-models-estimation-and-control" target="_blank" rel="noreferrer">Maybeck, <em>Stochastic Models, Estimation, and Control</em></a></td><td>The rigorous Kalman filter foundation.</td></tr><tr><td><a href="https://www.artechhouse.com/Principles-of-GNSS-Inertial-and-Multisensor-Integrated-Navigation-Systems-Third-Edition-P2106.aspx" target="_blank" rel="noreferrer">Groves, <em>Principles of GNSS, Inertial, and Multisensor Integrated Navigation Systems</em></a></td><td>Inertial navigation and sensor fusion, with engineering detail.</td></tr><tr><td><a href="https://ntrs.nasa.gov/citations/19950005007" target="_blank" rel="noreferrer">NASA Reference Publication 1311: Quaternion FAQ</a></td><td>Conventions, composition, and the traps.</td></tr><tr><td><a href="https://www.youtube.com/playlist?list=PLMrJAkhIeNNR20Mz-VpzgfQs5zrYi085m" target="_blank" rel="noreferrer">Steve Brunton, <em>Control Bootcamp</em></a></td><td>Intuition for state space, LQR, and observability.</td></tr><tr><td><a href="https://www.youtube.com/user/ControlLectures" target="_blank" rel="noreferrer">Brian Douglas, Control System Lectures</a></td><td>PID, frequency response, and practical intuition.</td></tr><tr><td><a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT 16.31 / 16.323</a></td><td>Full courses on estimation and control, free.</td></tr><tr><td><a href="https://python-control.readthedocs.io/" target="_blank" rel="noreferrer">APMonitor / Python Control</a></td><td>Quick LQR, step response, and pole placement in Python.</td></tr></tbody></table><p><strong>A caution:</strong> control theory is endless. For this path, stop at: state space, PID, LQR, observability, discretization, saturation, and delay. Then go build. The exotic material can wait until a job asks for it.</p><h2 id="orbital-mechanics-and-mission-design-tools" tabindex="-1">Orbital mechanics and mission design tools <a class="header-anchor" href="#orbital-mechanics-and-mission-design-tools" aria-label="Permalink to &quot;Orbital mechanics and mission design tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://www.ansys.com/products/missions/ansys-stk" target="_blank" rel="noreferrer">STK</a></td><td>High-fidelity scenario analysis: orbits, access, lighting, coverage, sensors. You have access; use it.</td></tr><tr><td><a href="https://gmat.sourceforge.net/" target="_blank" rel="noreferrer">GMAT</a></td><td>Free trajectory design, optimization, and ephemeris generation.</td></tr><tr><td><a href="https://naif.jpl.nasa.gov/naif/" target="_blank" rel="noreferrer">SPICE</a></td><td>Ephemerides, frames, and time kernels. The toolkit behind a lot of mission software.</td></tr><tr><td><a href="https://docs.poliastro.space/" target="_blank" rel="noreferrer">poliastro</a></td><td>Python orbital mechanics for quick calculations and plots.</td></tr><tr><td><a href="https://rhodesmill.org/skyfield/" target="_blank" rel="noreferrer">Skyfield</a></td><td>Python ephemerides and sky geometry.</td></tr><tr><td><a href="https://lunar.gsfc.nasa.gov/" target="_blank" rel="noreferrer">LRO/LOLA data</a></td><td>Topography and gravity products for lunar scenarios.</td></tr><tr><td><a href="https://ssd.jpl.nasa.gov/horizons/" target="_blank" rel="noreferrer">NASA Horizons</a></td><td>Ephemerides for almost anything in the solar system.</td></tr></tbody></table><p><strong>STK advice:</strong> learn four things well — scenario time and frame, satellite propagation, target/site definition, and one report (access or lighting). Then automate the same study with the Object Model. Do not try to learn every STK module.</p><h2 id="matlab-simulink-and-code-generation" tabindex="-1">MATLAB, Simulink, and code generation <a class="header-anchor" href="#matlab-simulink-and-code-generation" aria-label="Permalink to &quot;MATLAB, Simulink, and code generation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://matlabacademy.mathworks.com/" target="_blank" rel="noreferrer">MATLAB Onramp</a></td><td>If you are new to MATLAB, two hours is enough to start.</td></tr><tr><td><a href="https://matlabacademy.mathworks.com/" target="_blank" rel="noreferrer">Simulink Onramp</a></td><td>Blocks, signals, solvers, and a first model.</td></tr><tr><td><a href="https://www.mathworks.com/products/simcontrol.html" target="_blank" rel="noreferrer">Simulink Control Design</a></td><td>Linearization and PID tuning.</td></tr><tr><td><a href="https://www.mathworks.com/products/embedded-coder.html" target="_blank" rel="noreferrer">Embedded Coder</a></td><td>Generating production C from models.</td></tr><tr><td><a href="https://www.mathworks.com/products/requirements.html" target="_blank" rel="noreferrer">Simulink Requirements / Test</a></td><td>Traceability and model-based test, if your license includes it.</td></tr><tr><td><a href="https://www.mathworks.com/products/aerospace-blockset.html" target="_blank" rel="noreferrer">MATLAB Aerospace Blockset</a></td><td>Reference models for 6DOF and environment.</td></tr><tr><td><a href="https://www.mathworks.com/examples/" target="_blank" rel="noreferrer">MathWorks Examples</a></td><td>Search &quot;lunar lander&quot;, &quot;6DOF&quot;, &quot;Kalman filter&quot;.</td></tr></tbody></table><p><strong>Cost note:</strong> MATLAB toolboxes are expensive and license-dependent. If a toolbox is missing, implement the concept in Python or C++ instead of skipping it. The concept is the portable part.</p><h2 id="c-linux-and-tooling" tabindex="-1">C++, Linux, and tooling <a class="header-anchor" href="#c-linux-and-tooling" aria-label="Permalink to &quot;C++, Linux, and tooling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://en.cppreference.com/" target="_blank" rel="noreferrer">cppreference</a></td><td>The reference. Not a tutorial.</td></tr><tr><td><a href="https://www.learncpp.com/" target="_blank" rel="noreferrer">Learn C++</a></td><td>A structured tutorial if you need one.</td></tr><tr><td><a href="https://isocpp.github.io/CppCoreGuidelines/" target="_blank" rel="noreferrer">C++ Core Guidelines</a></td><td>Ownership, lifetime, and interface rules.</td></tr><tr><td><a href="https://godbolt.org/" target="_blank" rel="noreferrer">Compiler Explorer</a></td><td>See what the compiler actually emits; check for allocations and unexpected code.</td></tr><tr><td><a href="https://cmake.org/documentation/" target="_blank" rel="noreferrer">CMake documentation</a></td><td>Targets, toolchains, and cross-compilation.</td></tr><tr><td><a href="https://ninja-build.org/" target="_blank" rel="noreferrer">Ninja</a></td><td>Fast builds; the default generator for many embedded projects.</td></tr><tr><td><a href="https://sourceware.org/gdb/documentation/" target="_blank" rel="noreferrer">GDB documentation</a></td><td>Breakpoints, watchpoints, core dumps, remote targets.</td></tr><tr><td><a href="https://valgrind.org/" target="_blank" rel="noreferrer">Valgrind</a></td><td>Memory errors and leaks on the host.</td></tr><tr><td><a href="https://github.com/google/sanitizers" target="_blank" rel="noreferrer">Sanitizers</a></td><td>ASan, UBSan, and TSan for host testing.</td></tr><tr><td><a href="https://perf.wiki.kernel.org/" target="_blank" rel="noreferrer">perf</a></td><td>Timing and cache analysis on Linux.</td></tr><tr><td><a href="https://www.wireshark.org/" target="_blank" rel="noreferrer">Wireshark</a></td><td>Packet capture for network and serial-over-TCP test harnesses.</td></tr></tbody></table><h2 id="testing-and-verification" tabindex="-1">Testing and verification <a class="header-anchor" href="#testing-and-verification" aria-label="Permalink to &quot;Testing and verification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://docs.pytest.org/" target="_blank" rel="noreferrer">pytest</a></td><td>Fixtures, parametrization, and machine-readable reports.</td></tr><tr><td><a href="https://pytest-html.readthedocs.io/" target="_blank" rel="noreferrer">pytest-html</a></td><td>Human-readable test reports.</td></tr><tr><td><a href="https://google.github.io/googletest/" target="_blank" rel="noreferrer">GoogleTest</a></td><td>C++ unit testing, mocks, and death tests.</td></tr><tr><td><a href="https://github.com/catchorg/Catch2" target="_blank" rel="noreferrer">Catch2</a></td><td>A lighter C++ test framework.</td></tr><tr><td><a href="https://gcc.gnu.org/onlinedocs/gcc/Gcov.html" target="_blank" rel="noreferrer">gcov / lcov</a></td><td>Coverage measurement.</td></tr><tr><td><a href="https://cppcheck.sourceforge.io/" target="_blank" rel="noreferrer">Cppcheck</a></td><td>Static analysis for C++.</td></tr><tr><td><a href="https://clang.llvm.org/extra/clang-tidy/" target="_blank" rel="noreferrer">Clang-Tidy</a></td><td>Static analysis and modernization checks.</td></tr><tr><td><a href="https://www.jenkins.io/" target="_blank" rel="noreferrer">Jenkins</a> / <a href="https://docs.github.com/en/actions" target="_blank" rel="noreferrer">GitHub Actions</a></td><td>CI, nightly regression, and artifact retention.</td></tr><tr><td><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA SWEHB</a></td><td>What evidence a reviewer expects.</td></tr></tbody></table><p><strong>The one habit that matters:</strong> make the test suite runnable with one command from a fresh checkout. Everything else is detail.</p><h2 id="space-environment-and-mission-context" tabindex="-1">Space environment and mission context <a class="header-anchor" href="#space-environment-and-mission-context" aria-label="Permalink to &quot;Space environment and mission context&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://lunar.gsfc.nasa.gov/" target="_blank" rel="noreferrer">NASA LRO</a></td><td>Mission overview, instruments, and data.</td></tr><tr><td><a href="https://www.lpi.usra.edu/publications/books/lunar_sourcebook/" target="_blank" rel="noreferrer">Lunar Sourcebook</a></td><td>Regolith, thermal, and surface science.</td></tr><tr><td><a href="https://www.nasa.gov/history/alsj/" target="_blank" rel="noreferrer">Apollo Lunar Surface Journal</a></td><td>Crew debriefs, landing timelines, and real anomalies.</td></tr><tr><td><a href="https://ntrs.nasa.gov/" target="_blank" rel="noreferrer">NASA Technical Reports Server (NTRS)</a></td><td>Papers on guidance, navigation, and lander design.</td></tr><tr><td><a href="https://www.nasa.gov/" target="_blank" rel="noreferrer">NASA Spaceflight</a></td><td>Program news and mission updates.</td></tr><tr><td><a href="https://www.nasa.gov/artemis/" target="_blank" rel="noreferrer">Artemis</a></td><td>The current lunar program context.</td></tr></tbody></table><h2 id="communities-and-staying-current" tabindex="-1">Communities and staying current <a class="header-anchor" href="#communities-and-staying-current" aria-label="Permalink to &quot;Communities and staying current&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Why</th></tr></thead><tbody><tr><td><a href="https://github.com/nasa/cFS" target="_blank" rel="noreferrer">NASA cFS GitHub</a></td><td>Releases, issues, and examples.</td></tr><tr><td><a href="https://ccsds.org/" target="_blank" rel="noreferrer">CCSDS</a></td><td>Standards updates.</td></tr><tr><td><a href="https://www.aiaa.org/" target="_blank" rel="noreferrer">AIAA</a></td><td>Conferences and papers; student membership is affordable.</td></tr><tr><td><a href="https://ieee-aero.org/" target="_blank" rel="noreferrer">IEEE Aerospace Conference</a></td><td>Practical flight-software and GNC papers.</td></tr><tr><td><a href="https://digitalcommons.usu.edu/smallsat/" target="_blank" rel="noreferrer">Small Satellite Conference</a></td><td>Free proceedings, strong on real implementations.</td></tr><tr><td><a href="https://www.reddit.com/r/space/" target="_blank" rel="noreferrer">r/space</a></td><td>News, not engineering. Use sparingly.</td></tr><tr><td>Local university groups</td><td>Often the fastest way to find a mentor and a hardware project.</td></tr></tbody></table><h2 id="a-six-book-core-library" tabindex="-1">A six-book core library <a class="header-anchor" href="#a-six-book-core-library" aria-label="Permalink to &quot;A six-book core library&quot;">​</a></h2><p>If you buy nothing else:</p><ol><li><strong>Vallado</strong> — orbital mechanics and frames.</li><li><strong>Schaub &amp; Junkins</strong> — dynamics and control.</li><li><strong>Groves</strong> — navigation and sensor fusion.</li><li><strong>Barr Group embedded C standard</strong> — coding discipline.</li><li><strong>NASA Systems Engineering Handbook</strong> — how programs think.</li><li><strong>NPR 7150.2 + SWEHB</strong> — the compliance vocabulary.</li></ol><p>Everything else is a supplement.</p><h2 id="what-to-ignore-for-now" tabindex="-1">What to ignore, for now <a class="header-anchor" href="#what-to-ignore-for-now" aria-label="Permalink to &quot;What to ignore, for now&quot;">​</a></h2><ul><li>Full three-body trajectory optimization. Learn what an NRHO is; do not spend a month on it.</li><li>Propulsion thermodynamics and engine design. You need a thrust model, not a combustion model.</li><li>Detailed radiation-hardened electronics design. Know the failure modes and the software responses.</li><li>Exotic control methods (MPC, adaptive control, reinforcement learning) before you can tune a PID at a fixed sample rate.</li><li>Certifying anything. You can learn the evidence model without claiming a certification you do not have.</li><li>Benchmark-chasing on LeetCode. It will not help you explain a frame transform.</li></ul><h2 id="a-reading-protocol" tabindex="-1">A reading protocol <a class="header-anchor" href="#a-reading-protocol" aria-label="Permalink to &quot;A reading protocol&quot;">​</a></h2><p>For any paper or document:</p><ol><li>Read the abstract, figures, and conclusion first.</li><li>Write down the problem, the assumption, and the result in three sentences.</li><li>Find the one equation or architecture diagram you would reuse.</li><li>Decide whether it changes anything you are building. If not, stop.</li><li>If it does, add a test or a note to your project, not just a bookmark.</li></ol><p>The goal is not to have read more. It is to have fewer unknowns between you and a working descent.</p><p>Next: <a href="./glossary.html">glossary</a> or <a href="./formulas.html">formula sheet</a>.</p>',39)])])}const g=e(n,[["render",s]]);export{u as __pageData,g as default};
